useEffect(() => {
  fetchBooks()
    .then((data) => setBooks(data))
    .finally(() => setLoading(false));
}, []); // [] : une seule fois

useEffect(() => {
  let ignore = false;
  fetchBooks()
    .then((d) => {
      if (!ignore) setBooks(d);
    })
    .catch((err) => {
      if (!ignore) setError(err.message);
    })
    .finally(() => {
      if (!ignore) setLoading(false);
    });
  return () => { ignore = true; };
}, []);

if (error) {
  return <p role="alert">Erreur : {error}</p>;
}

